 1 | import { useState, useCallback } from "react";
 2 | import type { Track } from "../types";
 3 | 
 4 | const HISTORY_STORAGE_KEY = "llama-player-history";
 5 | const MAX_HISTORY = 100;
 6 | 
 7 | interface HistoryEntry {
 8 |   track: Track;
 9 |   playedAt: number; // timestamp
10 | }
11 | 
12 | function loadHistoryFromStorage(): HistoryEntry[] {
13 |   try {
14 |     const stored = localStorage.getItem(HISTORY_STORAGE_KEY);
15 |     if (!stored) return [];
16 |     const parsed = JSON.parse(stored);
17 |     if (!Array.isArray(parsed)) return [];
18 |     return parsed.filter(
19 |       (entry: unknown): entry is HistoryEntry =>
20 |         typeof entry === "object" &&
21 |         entry !== null &&
22 |         "track" in entry &&
23 |         "playedAt" in entry
24 |     );
25 |   } catch {
26 |     return [];
27 |   }
28 | }
29 | 
30 | function saveHistoryToStorage(entries: HistoryEntry[]): void {
31 |   try {
32 |     // Keep only the latest MAX_HISTORY entries
33 |     const trimmed = entries.slice(0, MAX_HISTORY);
34 |     localStorage.setItem(HISTORY_STORAGE_KEY, JSON.stringify(trimmed));
35 |   } catch (err) {
36 |     console.error("[Llama Player] Erro ao salvar histórico:", err);
37 |   }
38 | }
39 | 
40 | export function useHistory() {
41 |   const [entries, setEntries] = useState<HistoryEntry[]>(loadHistoryFromStorage);
42 | 
43 |   const addEntry = useCallback((track: Track) => {
44 |     setEntries((prev) => {
45 |       // Remove duplicate if exists (same track id)
46 |       const filtered = prev.filter((e) => e.track.id !== track.id);
47 |       const newEntry: HistoryEntry = {
48 |         track,
49 |         playedAt: Date.now(),
50 |       };
51 |       const updated = [newEntry, ...filtered];
52 |       saveHistoryToStorage(updated);
53 |       return updated;
54 |     });
55 |   }, []);
56 | 
57 |   const clear = useCallback(() => {
58 |     setEntries([]);
59 |     saveHistoryToStorage([]);
60 |   }, []);
61 | 
62 |   return { entries, addEntry, clear };
63 | }
